  INDEX `idx_source`(`source`) USING BTREE,
  INDEX `idx_user_source`(`user_id`, `source`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户数据源连接凭证表' ROW_FORMAT = Dynamic;

