INSERT INTO `canvas_template` VALUES ('0', 1761808018662, '2025-10-30 15:06:58', 1761808018662, '2025-10-30 15:06:58', 'data:image/png;base64,', 'WebSearch Assistant', 'A chat assistant template that integrates information extracted from a knowledge base and web searches to respond to queries. Let\'s begin by setting up your knowledge base in \'Retrieval\'!', 'chatbot', '{\"answer\": [], \"components\": {\"Answer:PoorMapsCover\": {\"downstream\": [\"RewriteQuestion:OrangeBottlesSwim\"], \"obj\": {\"component_name\": \"Answer\", \"inputs\": [], \"output\": null, \"params\": {\"debug_inputs\": [], \"inputs\": [], \"message_history_window_size\": 22, \"output\": null, \"output_var_name\": \"output\", \"post_answers\": [], \"query\": []}}, \"upstream\": [\"begin\", \"Generate:ItchyRiversDrum\"]}, \"Baidu:OliveAreasCall\": {\"downstream\": [\"Generate:ItchyRiversDrum\"], \"obj\": {\"component_name\": \"Baidu\", \"inputs\": [], \"output\": null, \"params\": {\"debug_inputs\": [], \"inputs\": [], \"message_history_window_size\": 22, \"output\": null, \"output_var_name\": \"output\", \"query\": [{\"component_id\": \"KeywordExtract:BeigeTipsStand\", \"type\": \"reference\"}], \"top_n\": 2}}, \"upstream\": [\"KeywordExtract:BeigeTipsStand\"]}, \"DuckDuckGo:SoftButtonsRefuse\": {\"downstream\": [\"Generate:ItchyRiversDrum\"], \"obj\": {\"component_name\": \"DuckDuckGo\", \"inputs\": [], \"output\": null, \"params\": {\"channel\": \"text\", \"debug_inputs\": [], \"inputs\": [], \"message_history_window_size\": 22, \"output\": null, \"output_var_name\": \"output\", \"query\": [{\"component_id\": \"KeywordExtract:BeigeTipsStand\", \"type\": \"reference\"}], \"top_n\": 2}}, \"upstream\": [\"KeywordExtract:BeigeTipsStand\"]}, \"Generate:ItchyRiversDrum\": {\"downstream\": [\"Answer:PoorMapsCover\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": true, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": 