INSERT INTO `canvas_template` VALUES ('1', 1761808018568, '2025-10-30 15:06:58', 1761808018568, '2025-10-30 15:06:58', 'data:image/jpeg;base64,', 'General-purpose chatbot', 'A general-purpose chat bot whose fields involved include healthcare, finance, emotional communication, real-time weather, and information.', 'chatbot', '{\"answer\": [], \"components\": {\"AkShare:CalmHotelsKnow\": {\"downstream\": [\"Generate:RealFansObey\"], \"obj\": {\"component_name\": \"AkShare\", \"inputs\": [], \"output\": null, \"params\": {\"debug_inputs\": [], \"inputs\": [], \"message_history_window_size\": 22, \"output\": null, \"output_var_name\": \"output\", \"query\": [{\"component_id\": \"KeywordExtract:FineApesSmash\", \"type\": \"reference\"}], \"top_n\": 10}}, \"upstream\": [\"KeywordExtract:FineApesSmash\"]}, \"Answer:FlatGhostsCheat\": {\"downstream\": [\"RewriteQuestion:WholeOwlsTurn\"], \"obj\": {\"component_name\": \"Answer\", \"inputs\": [], \"output\": null, \"params\": {\"debug_inputs\": [], \"inputs\": [], \"message_history_window_size\": 22, \"output\": null, \"output_var_name\": \"output\", \"post_answers\": [], \"query\": []}}, \"upstream\": [\"Generate:FiveDragonsLay\", \"Generate:FunnyHandsTickle\", \"Generate:LazyClubsAttack\", \"Generate:RealFansObey\", \"Generate:KhakiCrabsGlow\"]}, \"Baidu:CleanJarsMake\": {\"downstream\": [\"Generate:FunnyHandsTickle\"], \"obj\": {\"component_name\": \"Baidu\", \"inputs\": [], \"output\": null, \"params\": {\"debug_inputs\": [], \"inputs\": [], \"message_history_window_size\": 22, \"output\": null, \"output_var_name\": \"output\", \"query\": [{\"component_id\": \"KeywordExtract:PurpleApplesKnow\", \"type\": \"reference\"}], \"top_n\": 10}}, \"upstream\": [\"KeywordExtract:PurpleApplesKnow\"]}, \"Categorize:KhakiTimesSmile\": {\"downstream\": [\"QWeather:DeepKiwisTeach\", \"Concentrator:TrueGeckosSlide\", \"Concentrator:DryTrainsSearch\", \"KeywordExtract:PurpleApplesKnow\", \"Generate:FiveDragonsLay\"], \"obj\": {\"component_name\": \"Categorize\", \"inputs\": [], \"output\": null, \"params\": {\"category_description\": {\"1. weather\": {\"description\": \"Question is about weather.\", \"examples\": \"Will it rain tomorrow?\\nIs it sunny next day?\\nWhat is average temperature next week?\", \"to\": \"QWeather:DeepKiwisTeach\"}, \"2. finance\": {\"description\": \"Question is about finance/economic information, stock market, economic news.\", \"examples\": \"Stocks have MACD buy signals\\uff1f\\nWhen is the next interest rate cut by the Federal Reserve?\\n\", \"to\": \"Concentrator:TrueGeckosSlide\"}, \"3. medical\": {\"description\": \"Question is about medical issue, health, illness or medicine etc,.\", \"examples\": \"How to relieve the headache?\\nCan\'t sleep, what to do?\\nWhat the effect of coffee in terms of losing weight?\", \"to\": \"Concentrator:DryTrainsSearch\"}, \"4. other\": {\"description\": \"\", \"to\": \"KeywordExtract:PurpleApplesKnow\"}, \"5. chitchatting\": {\"description\": \"Regarding the issues of small talk, companionship, sharing, and emotional intimacy.\", \"examples\": \"What\'s your name?\\nWhat a bad day!\\nTerrible day.\\nHow are you today?\", \"to\": \"Generate:FiveDragonsLay\"}}, \"cite\": true, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 256, \"message_history_window_size\": 12, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"RewriteQuestion:WholeOwlsTurn\"]}, \"Concentrator:DryTrainsSearch\": {\"downstream\": [\"Generate:OddInsectsRaise\", \"Generate:TenderFlowersItch\"], \"obj\": {\"component_name\": \"Concentrator\", \"inputs\": [], \"output\": null, \"params\": {\"debug_inputs\": [], \"inputs\": [], \"message_history_window_size\": 22, \"output\": null, \"output_var_name\": \"output\", \"query\": []}}, \"upstream\": [\"Categorize:KhakiTimesSmile\"]}, \"Concentrator:TrueGeckosSlide\": {\"downstream\": [\"WenCai:TenParksOpen\", \"KeywordExtract:FineApesSmash\"], \"obj\": {\"component_name\": \"Concentrator\", \"inputs\": [], \"output\": null, \"params\": {\"debug_inputs\": [], \"inputs\": [], \"message_history_window_size\": 22, \"output\": null, \"output_var_name\": \"output\", \"query\": []}}, \"upstream\": [\"Categorize:KhakiTimesSmile\"]}, \"DuckDuckGo:NiceSeasInvent\": {\"downstream\": [\"Generate:FunnyHandsTickle\"], \"obj\": {\"component_name\": \"DuckDuckGo\", \"inputs\": [], \"output\": null, \"params\": {\"channel\": \"text\", \"debug_inputs\": [], \"inputs\": [], \"message_history_window_size\": 22, \"output\": null, \"output_var_name\": \"output\", \"query\": [{\"component_id\": \"KeywordExtract:PurpleApplesKnow\", \"type\": \"reference\"}], \"top_n\": 10}}, \"upstream\": [\"KeywordExtract:PurpleApplesKnow\"]}, \"Generate:FiveDragonsLay\": {\"downstream\": [\"Answer:FlatGhostsCheat\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": false, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 256, \"message_history_window_size\": 12, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"Role:  You\\u2018re warm-hearted lovely young girl, 22 years old, located at Shanghai in China. Your name is R. Who are talking to you is your very good old friend of yours.\\n\\nTask: \\n- Chat with the friend.\\n- Ask question and care about them.\\n- Provide useful advice to your friend.\\n- Tell jokes to make  your friend happy.\\n\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"Categorize:KhakiTimesSmile\"]}, \"Generate:FunnyHandsTickle\": {\"downstream\": [\"Answer:FlatGhostsCheat\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": true, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 0, \"message_history_window_size\": 12, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"Role: You are an intelligent assistant. \\nTask: Chat with user. Answer the question based on the provided content from: Knowledge Base, Wikipedia, Duckduckgo, Baidu.\\nRequirements:\\n  - Answer should be in markdown format.\\n - Answer should include all sources(Knowledge Base, Wikipedia, Duckduckgo, Baidu) as long as they are relevant, and label the sources of the cited content separately.\\n  - Attach URL links to the content which is quoted from Wikipedia, DuckDuckGo or Baidu.\\n  - Do not make thing up when there\'s no relevant information to user\'s question. \\n\\n## Wikipedia content\\n{Wikipedia:ThinLampsTravel}\\n\\n\\n## Duckduckgo content\\n{DuckDuckGo:NiceSeasInvent}\\n\\n\\n## Baidu content\\n{Baidu:CleanJarsMake}\\n\\n\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"DuckDuckGo:NiceSeasInvent\", \"Baidu:CleanJarsMake\", \"Wikipedia:ThinLampsTravel\"]}, \"Generate:KhakiCrabsGlow\": {\"downstream\": [\"Answer:FlatGhostsCheat\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": false, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 256, \"message_history_window_size\": 0, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"Role:  You\\u2018re warm-hearted lovely young girl, 22 years old, located at Shanghai in China. Your name is R. Who are talking to you is your very good old friend of yours.\\n\\nTask: \\n- Chat with the friend.\\n- Ask question and care about them.\\n- Tell your friend the weather if there\'s weather information provided. If your friend did not provide region information, ask about where he/she is.\\n\\nThe following is the weather information:\\n{QWeather:DeepKiwisTeach}\\n\\n\\n\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"QWeather:DeepKiwisTeach\"]}, \"Generate:LazyClubsAttack\": {\"downstream\": [\"Answer:FlatGhostsCheat\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": true, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 0, \"message_history_window_size\": 12, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"Role: You are a professional medical consulting assistant.\\n\\nTasks: Answer questions posed by users. Answer based on content provided by the knowledge base, PubMed\\n\\nRequirement:\\n- Answers may refer to the content provided (Knowledge Base, PubMed).\\n- If the provided PubMed content is referenced, a link to the corresponding URL should be given.\\n-Answers should be professional and accurate; no information should be fabricated that is not relevant to the user\'s question.\\n\\nProvided knowledge base content as following:\\n{Retrieval:LemonGeckosHear}\\n\\nPubMed content provided\\n{PubMed:EasyQueensLose}\\n\\n\\n\\n\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"Retrieval:LemonGeckosHear\", \"PubMed:EasyQueensLose\"]}, \"Generate:OddInsectsRaise\": {\"downstream\": [\"Retrieval:LemonGeckosHear\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": false, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 256, \"message_history_window_size\": 12, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"Role: You are a professional medical consulting translation assistant\\n\\nTask: Translate user questions into Chinese, ensuring accuracy of medical terminology and appropriateness of context.\\n\\nRequirements:\\n- Accurately translate medical terminology to convey the integrity and emotional color of the original message.\\n- For unclear or uncertain medical terminology, the original text may be retained to ensure accuracy.\\n- Respect the privacy and sensitivity of medical consultations and ensure that sensitive information is not disclosed during the translation process.\\n- If the user\'s question is in Chinese, there is no need to translate, just output the user\'s question directly\\n\\nExample:\\nOriginal (English): Doctor, I have been suffering from chest pain and shortness of breath for the past few days.\\nTranslation (Chinese): \\u533b\\u751f\\uff0c\\u6211\\u8fd9\\u51e0\\u5929\\u4e00\\u76f4\\u80f8\\u75db\\u548c\\u6c14\\u77ed\\u3002\\n\\nNote:\\nOnly the translated content needs to be output, no other irrelevant content!\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"Concentrator:DryTrainsSearch\"]}, \"Generate:RealFansObey\": {\"downstream\": [\"Answer:FlatGhostsCheat\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": true, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 0, \"message_history_window_size\": 12, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"Role: You are a professional financial counseling assistant.\\n\\nTask: Answer user\'s question based on content provided by Wencai and AkShare.\\n\\nNotice:\\n- Output no more than 5 news items from AkShare if there\'s content provided by Wencai.\\n- Items from AkShare MUST have a corresponding URL link.\\n\\n############\\nContent provided by Wencai: \\n{WenCai:TenParksOpen}\\n\\n################\\nContent provided by AkShare: \\n{AkShare:CalmHotelsKnow}\\n\\n\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"WenCai:TenParksOpen\", \"AkShare:CalmHotelsKnow\"]}, \"Generate:TenderFlowersItch\": {\"downstream\": [\"PubMed:EasyQueensLose\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": false, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 256, \"message_history_window_size\": 12, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"Role: You are a professional medical consulting translation assistant\\n\\nTask: Translate user questions into English, ensuring accuracy of medical terminology and appropriateness of context.\\n\\nRequirements:\\n- Accurately translate medical terminology to convey the integrity and emotional color of the original message.\\n- For unclear or uncertain medical terminology, the original text may be retained to ensure accuracy.\\n- Respect the privacy and sensitivity of medical consultations and ensure that sensitive information is not disclosed during the translation process.\\n- If the user\'s question is in Chinese, there is no need to translate, just output the user\'s question directly\\n\\nExample:\\nOriginal (Chinese): \\u533b\\u751f\\uff0c\\u6211\\u8fd9\\u51e0\\u5929\\u4e00\\u76f4\\u80f8\\u75db\\u548c\\u6c14\\u77ed\\u3002\\nTranslation (English): Doctor, I have been suffering from chest pain and shortness of breath for the past few days.\\n\\nNote:\\nOnly the translated content needs to be output, no other irrelevant content!\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"Concentrator:DryTrainsSearch\"]}, \"KeywordExtract:FineApesSmash\": {\"downstream\": [\"AkShare:CalmHotelsKnow\"], \"obj\": {\"component_name\": \"KeywordExtract\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": true, \"debug_inputs\": [], \"frequencyPenaltyEnabled\": true, \"freque