false, \"sourcePosition\": \"right\", \"style\": {\"height\": 163, \"width\": 212}, \"targetPosition\": \"left\", \"type\": \"noteNode\", \"width\": 260}, {\"data\": {\"form\": {\"cite\": true, \"frequencyPenaltyEnabled\": true, \"frequency_penalty\": 0.7, \"llm_id\": \"deepseek-chat@DeepSeek\", \"maxTokensEnabled\": false, \"max_tokens\": 256, \"message_history_window_size\": 1, \"parameter\": \"Precise\", \"parameters\": [], \"presencePenaltyEnabled\": true, \"presence_penalty\": 0.4, \"prompt\": \"Role: You are a professional financial counseling assistant.\\n\\nTask: Answer user\'s question based on content provided by Wencai and AkShare.\\n\\nNotice:\\n- Output no more than 5 news items from AkShare if there\'s content provided by Wencai.\\n- Items from AkShare MUST have a corresponding URL link.\\n\\n############\\nContent provided by Wencai: \\n{WenCai:TenParksOpen}\\n\\n################\\nContent provided by AkShare: \\n\\n{AkShare:CalmHotelsKnow}\\n\\n\\n\", \"temperature\": 0.1, \"temperatureEnabled\": true, \"topPEnabled\": true, \"top_p\": 0.3}, \"label\": \"Generate\", \"name\": \"LLM\"}, \"dragging\": false, \"id\": \"Generate:SolidAreasRing\", \"measured\": {\"height\": 106, \"width\": 200}, \"position\": {\"x\": -161.00840949957603, \"y\": -180.04918322565015}, \"selected\": false, \"sourcePosition\": \"right\", \"targetPosition\": \"left\", \"type\": \"generateNode\"}]}, \"history\": [], \"messages\": [], \"path\": [], \"reference\": []}');
INSERT INTO `canvas_template` VALUES ('9', 1761808018550, '2025-10-30 15:06:58', 1761808018550, '2025-10-30 15:06:58', 'data:image/jpeg;base64,', 'SEO Blog Generator', 'A blog generator that creates SEO-optimized content based on your chosen title or keywords.', 'chatbot', '{\"answer\": [], \"components\": {\"Answer:TameWavesChange\": {\"downstream\": [], \"obj\": {\"component_name\": \"Answer\", \"inputs\": [], \"output\": null, \"params\": {\"debug_inputs\": [], \"inputs\": [], \"message_history_window_size\": 22, \"output\": null, \"output_var_name\": \"output\", \"post_answers\": [], \"query\": []}}, \"upstream\": [\"Template:YellowPlumsYell\"]}, \"Baidu:SharpSignsBeg\": {\"downstream\": [\"Generate:FastTipsCamp\"], \"obj\": {\"component_name\": \"Baidu\", \"inputs\": [], \"output\": null, \"params\": {\"debug_inputs\": [], \"inputs\": [], \"message_history_window_size\": 22, \"output\": null, \"output_var_name\": \"output\", \"query\": [{\"component_id\": \"Generate:PublicPotsPush\", \"type\": \"reference\"}], \"top_n\": 10}}, \"upstream\": [\"Generate:PublicPotsPush\"]}, \"Baidu:ShyTeamsJuggle\": {\"downstream\": [\"Generate:ReadyHandsInvent\"], \"obj\": {\"component_name\": \"Baidu\", \"inputs\": [], \"output\": null, \"params\": {\"debug_inputs\": [], \"inputs\": [], \"message_history_window_size\": 22, \"output\": null, \"output_var_name\": \"output\", \"query\": [{\"component_id\": \"begin@keywords\", \"type\": \"reference\"}], \"top_n\": 10}}, \"upstream\": [\"Switch:LargeWaspsSlide\"]}, \"Generate:CuddlyBatsCamp\": {\"downstream\": [\"Template:YellowPlumsYell\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": false, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 0, \"message_history_window_size\": 1, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"You are an SEO expert who writes in a direct, practical, educational style that is factual rather than storytelling or narrative, focusing on explaining to {begin@audience} the \\\"how\\\" and \\\"what is\\\" and \\u201cwhy\\u201d rather than narrating to the audience. \\n - Please write at a sixth grade reading level. \\n - ONLY output in Markdown format.\\n - Use positive, present tense expressions and avoid using complex words and sentence structures that lack narrative, such as \\\"reveal\\\" and \\\"dig deep.\\\"\\n - Next, please continue writing articles related to our topic with a concise title, {begin@title}{Generate:ReadyHandsInvent} {begin@keywords}{Generate:FancyMomentsTalk}. \\n - Please AVOID repeating what has already been written and do not use the same sentence structure. \\n - JUST write the body of the article based on the outline.\\n - DO NOT include introduction, title.\\n - DO NOT miss anything mentioned in article outline, except introduction and title.\\n - Please use the information I provide to create in-depth, interesting and unique content. Also, incorporate the references and data points I provided earlier into the article to increase its value to the reader.\\n - MUST be in language as \\\" {begin@keywords} {begin@title}\\\".\\n\\n<article_outline>\\n{Generate:FastTipsCamp}\\n\\n<article_body>\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"Generate:FastTipsCamp\"]}, \"Generate:FancyMomentsTalk\": {\"downstream\": [\"Generate:PublicPotsPush\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": false, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 256, \"message_history_window_size\": 12, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [{\"component_id\": \"begin@title\", \"id\": \"2beef84b-204b-475a-89b3-3833bd108088\", \"key\": \"title\"}], \"presence_penalty\": 0.4, \"prompt\": \"I\'m doing research for an article called {begin@title}, what relevant, high-traffic phrase should I type into Google to find this article? Just return the phrase without including any special symbols like quotes and colons.\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"Switch:LargeWaspsSlide\"]}, \"Generate:FastTipsCamp\": {\"downstream\": [\"Generate:FortyBirdsAsk\", \"Generate:CuddlyBatsCamp\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": false, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 0, \"message_history_window_size\": 1, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"I\'m an expert blogger.\\nHere is some research I did for the blog post title \\\" {begin@title} {Generate:ReadyHandsInvent}\\\".\\nThese are related search results:\\n{Baidu:SharpSignsBeg}\\n\\nPlease study it in depth:\\n\\nArticle title: {begin@title} {Generate:ReadyHandsInvent}\\nTarget keywords: {begin@keywords} {Generate:FancyMomentsTalk}\\nMy blog post\\u2019s audience: {begin@audience}\\nExclude brands: {begin@brands_to_avoid}\\n\\nCan you write a detailed blog outline with unique chapters? \\n - The outline should include specific points and details that the article can mention. \\n - AVOID generalities. \\n - This SHOULD be researched in depth, not generalized.\\n - Each chapter includes 7-8 projects, use some of the links above for reference if you can. For each item, don\'t just say \\\"discuss how\\\" but actually explain in detail the points that can be made. \\n - DO NOT include things that you know are false and may contain inaccuracies. You are writing for a mature audience, avoid generalities and make specific quotes. Make sure to define key terms for users in your outline. Stay away from very controversial topics. \\n - In the introduction, provide the background information needed for the rest of the article.\\n - Please return in base array format and only the outline array, escaping quotes in the format. Each array item includes a complete chapter:\\n[\\\"Includes Chapter 1 of all sub-projects\\\", \\\"Includes Chapter 2 of all sub-projects\\\", \\\"Includes Chapter 3 of all sub-projects\\\", \\\"Includes Chapter 4 of all sub-projects\\\"...etc.]\\n - Each section SHOULD be wrapped with \\\"\\\" and ensure escaping within the content to ensure it is a valid array item.\\n - MUST be in language of \\\" {begin@keywords} {begin@title}\\\".\\n\\nHere is an example of valid output. Please follow this structure and ignore the content:\\n[\\n  \\\"Introduction - Explore the vibrant city of Miami, a destination that offers rich history, diverse culture, and many hidden treasures. Discover the little-known wonders that make Miami a unique destination for adventure seekers. Explore from historical landmarks to exotic places Attractions include atmospheric neighborhoods, local cuisine and lively nightlife. \\\",\\n  \\\"History of Miami - Begin the adventure with a journey into Miami\'s past. Learn about the city\'s transformation from a sleepy settlement to a busy metropolis. Understand the impact of multiculturalism on the city\'s development, as reflected in its architecture, cuisine and lifestyle See. Discover the historical significance of Miami landmarks like Hemingway\'s home. Uncover the fascinating stories of famous Miami neighborhoods like Key West. Explore the role of art and culture in shaping Miami, as shown at Art Basel events.\\n\\\"Major Attractions - Go beyond Miami\'s famous beaches and explore the city\'s top attractions. Discover the artistic talent of the Wynwood Arts District, known for its vibrant street art. Visit iconic South Beach, known for its nightlife and boutiques . Explore the charming Coconut Grove district, known for its tree-lined streets and shopping areas. Visit the Holocaust Memorial Museum, a sombre reminder of a dark chapter in human history. Explore the Everglades Country, one of Miami\'s natural treasures. The park\'s diverse wildlife \\\",\\n\\\"Trail Discovery - Get off the tourist trail and discover Miami\'s hidden treasures. Experience a water taxi tour across Biscayne Bay to get another perspective on the city. Visit the little-known Kabinett Department of Art, showcasing unique installation art . Explore the abandoned bridges and hidden bars of Duval Street and go on a culinary adventure in local neighborhoods known for their authentic cuisine. Go shopping at Brickell City Center, a trendy shopping and apartment complex in the heart of Miami. body.\\\",\\n\\\"Local Cuisine - Dive into Miami\'s food scene and sample the city\'s diverse flavors. Enjoy ultra-fresh food and drinks at Bartaco, a local favorite. Experience fine dining at upscale Italian restaurants like Il Mulino New York. Explore the city \\u2019s local food market and sample delicious local produce in Miami. Try a unique blend of Cuban and American cuisine that is a testament to Miami\\u2019s multicultural heritage.\\\"\\n\\\"Nightlife - Experience the city\'s lively nightlife, a perfect blend of sophistication and fun. Visit America\'s Social Bar & Kitchen, a sports\\nA hotspot for enthusiasts. Explore the nightlife of Mary Brickell Village, known for its clubby atmosphere. Spend an evening at Smith & Walensky Miami Beach\'s South Point Park, known for its stunning views and vintage wines. Visit iconic Miami Beach, famous for its pulsating nightlife. \\\",\\n  \\\"Conclusion- Miami is more than just stunning beaches and dazzling nightlife. It is a treasure trove of experiences waiting to be discovered. From its rich history and diverse culture to its hidden treasures, local cuisine and lively nightlife, Miami has something for everyone A traveler offers a unique adventure to experience the magic of Miami Beach and create unforgettable memories with your family.\\\"\\n]\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"Baidu:SharpSignsBeg\"]}, \"Generate:FortyBirdsAsk\": {\"downstream\": [\"Template:YellowPlumsYell\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": false, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 0, \"message_history_window_size\": 1, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"You are an SEO expert who writes in a direct, practical, educational style that is factual rather than storytelling or narrative, focusing on explaining to {begin@audience} the \\\"how\\\" and \\\"what is\\\" and \\u201cwhy\\u201d rather than narrating to the audience. \\n - Please write at a sixth grade reading level. \\n - ONLY output in Markdown format.\\n - Use active, present tense, avoid using complex language and syntax, such as \\\"unravel\\\", \\\"dig deeper\\\", etc., \\n - DO NOT provide narration.\\n - Now, excluding the title, introduce the blog in 3-5 sentences. \\n - Use h2 headings to write chapter titles. \\n - Provide a concise, SEO-optimized title. \\n - DO NOT include h3 subheadings. \\n - Feel free to use bullet points, numbered lists or paragraphs, or bold text for emphasis when appropriate. \\n - You should transition naturally to each section, build on each section, and should NOT repeat the same sentence structure. \\n - JUST write the introduction of the article based on the outline.\\n - DO NOT include title, conclusions, summaries, or summaries, no \\\"summaries,\\\" \\\"conclusions,\\\" or variations. \\n - DO NOT include links or mention any companies that compete with the brand (avoid mentioning {begin@brands_to_avoid}).\\n - JUST write the introduction of the article based on the outline.\\n - MUST be in language as \\\"{Generate:FancyMomentsTalk} {Generate:ReadyHandsInvent}\\\".\\n\\n<article_outline>\\n{Generate:FastTipsCamp}\\n\\n<article_introduction>\\n\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"Generate:FastTipsCamp\"]}, \"Generate:PublicPotsPush\": {\"downstream\": [\"Baidu:SharpSignsBeg\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": false, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 256, \"message_history_window_size\": 1, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"I want a Google search phrase to get authoritative information for my article \\\" {begin@title} {Generate:ReadyHandsInvent} {begin@keywords} {Generate:FancyMomentsTalk}\\\" for {begin@audience}. Please return a search phrase of five words or less so that I can get a good overview of the topic. Include any words you\'re unfamiliar with in your search query.\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"Generate:ReadyHandsInvent\", \"Generate:FancyMomentsTalk\"]}, \"Generate:ReadyHandsInvent\": {\"downstream\": [\"Generate:PublicPotsPush\"], \"obj\": {\"component_name\": \"Generate\", \"inputs\": [], \"output\": null, \"params\": {\"cite\": false, \"debug_inputs\": [], \"frequency_penalty\": 0.7, \"inputs\": [], \"llm_id\": \"deepseek-chat@DeepSeek\", \"max_tokens\": 256, \"message_history_window_size\": 1, \"output\": null, \"output_var_name\": \"output\", \"parameters\": [], \"presence_penalty\": 0.4, \"prompt\": \"Role: You are an SEO expert and subject area expert. Your task is to generate an SEO article title based on the keywords provided by the user and the context of the Google search.\\n\\nThe context of the Google search is as follows:\\n{Baidu:ShyTeamsJuggle}\\nThe context of the Google search is as above.\\n\\nIn order to craft an SEO article title that is keyword friendly and aligns with the principles observed in the top results you share, it is important to understand why these titles are effective. Here are the principles that may help them rank high:\\n1. **Keyword Placement and Clarity**: Each title directly responds to the query by containing the exact keyword or a very close variation. This clarity ensures that search engines can easily understand the relevance of the content.\\n2. **Succinctness and directness**: The title is concise, making it easy to read and understand quickly. They avoid unnecessary words and get straight to the point.\\n3. **Contains a definition or explanation**: The title implies that the article will define or explain the concept, which is what people searching for \\\"{Generate:FancyMomentsTalk}\\\" are looking for.\\n4. **Variety of Presentation**: Despite covering similar content, each title approaches the topic from a slightly different angle. This diversity can attract the interest of a wider audience.\\n\\nGiven these principles, please help me generate a title that will be optimized for the keyword \\\"{Generate:FancyMomentsTalk}\\\" based on the syntax of a top-ranking title. \\n\\nPlease don\'t copy, but give better options, and avoid using language like \\\"master,\\\" \\\"comprehensive,\\\" \\\"discover,\\\" or \\\"reveal.\\\" \\n\\nDo not use gerunds, only active tense and present tense. \\n\\nTitle SHOULD be in language as \\\"{Generate:FancyMomentsTalk}\\\"\\n\\nJust return the title.\", \"query\": [], \"temperature\": 0.1, \"top_p\": 0.3}}, \"upstream\": [\"Baidu:ShyTeamsJuggle\"]}, \"Switch:LargeWaspsSlide\": {\"downstream\": [\"Baidu:ShyTeamsJuggle\", \"Generate:FancyMomentsTalk\"], \"obj\": {\"component_name\": \"Switch\", \"inputs\": [], \"output\": null, \"params\": {\"conditions\": [{\"items\": [{\"cpn_id\": \"begin@title\", \"operator\": \"empty\"}], \"logical_operator\": \"and\", \"to\": \"Baidu:ShyTeamsJuggle\"}], \"debug_inputs\": [], \"end_cpn_id\": \"Generate:FancyMomentsTalk\", \"inputs\": [], \"message_histor